  const mapSvg = (label) => `<svg viewBox="0 0 360 200" width="100%" style="display:block;background:#EAF1F8" role="img" aria-label="${esc(label)}"><g stroke="#fff" stroke-width="7">${[40, 110, 180, 250, 320].map((x) => `<path d="M${x} 0V200"/>`).join('')}${[40, 100, 160].map((y) => `<path d="M0 ${y}H360"/>`).join('')}</g><rect x="0" y="120" width="90" height="80" fill="#DCE5EF"/>${S.trip ? '<path d="M70 150 L180 150 L180 60 L300 60" fill="none" stroke="#C81E24" stroke-width="5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="70" cy="150" r="10" fill="#0B3B6E"/><circle cx="300" cy="60" r="10" fill="#0B3B6E"/>' : ''}<circle cx="${S.trip ? 180 : 180}" cy="${S.trip ? 105 : 100}" r="11" fill="#C81E24" stroke="#fff" stroke-width="3"/></svg>`;

