    <div class="card pad col" style="gap:0">${[['Nov 3', '$412.60'], ['Oct 27', '$388.15'], ['Oct 20', '$301.90']].map(([d, a]) => `<div class="row" style="border-top:1px solid var(--line);padding:10px 0"><span class="grow">${d}</span><span class="pill p-g">Paid</span><b style="width:90px;text-align:right">${a}</b></div>`).join('')}</div>
