    camOpen: () => { S.modal = { type: 'cam' }; render(); },
    camSnap: () => { S.proof = 'door-photo.jpg'; S.proofUrl = ''; S.modal = null; toast('Photo added.'); render(); },
    problem: () => { S.modal = { type: 'problem', v: 'wait' }; render(); },
    probPick: (d) => { S.modal.v = d.v; render(); },
    probSend: () => { const v = S.modal.v; S.modal = null; toast(v === 'unsafe' ? 'Support is calling you now. If you’re in danger, call 911.' : 'Support has your report and will text you shortly.'); render(); },
