    vehicleAsk: () => { S.modal = { type: 'vehicle', v: S.vehicle }; render(); },
    vehPick: (d) => { S.modal.v = d.v; render(); },
    vehSave: () => { const v = S.modal.v; S.modal = null; if (['Car', 'Moped'].includes(v) && !['Car', 'Moped'].includes(S.vehicle)) { toast(`Upload your license, delivery insurance and plate before driving a ${v.toLowerCase()} (prototype: switched).`); } else toast(`Vehicle set to ${v}.`); S.vehicle = v; render(); },
    docs: () => toast(['Car', 'Moped'].includes(S.vehicle) ? 'Photo ID, license and insurance verified. We’ll remind you before your license or insurance expires.' : 'Photo ID verified.'),
    notif: (d) => { S.notif[d.k] = !S.notif[d.k]; toast(S.notif[d.k] ? 'On.' : 'Off.'); },
    signOut: () => { S.online = false; clearTimeout(offerTimer); S.signedIn = false; S.stack = []; S.screen = 'welcome'; render(true); },
